/* 第07轮：只记录作品位置与任务摘要，不重建创作数据。 */
window.createCimoraNavigationModel=function(M,S){
 const episode=c=>c.c.kind==='episode',imported=c=>!episode(c)&&!!c.e.importDraft;
 const stages=c=>imported(c)?[['pages','原图与裁切'],['text','文字与剧情'],['entities','人物与场景'],['review','资料检查与交接']]:episode(c)?[['boards','镜头方案'],['motion','逐镜制作'],['audio','剪辑与声音'],['review','审阅与交付']]:[['story','脚本与资产'],['boards','逐格画面'],['comic','排版阅读'],['review','审阅与交付']];
 function current(c,params){return imported(c)?params?.get('import')||c.e.navigation?.import||'pages':c.e.stage==='assets'?'story':c.e.stage;}
 function url(c,stage=c.e.stage||'story',view=c.e.view||'flow',extra=''){return `/app/create/${c.p.id}/${c.c.id}?stage=${stage}&view=${view}${extra}`;}
 function remember(c,params){if(imported(c))c.e.view='flow';const sid=params?.get('shot')||params?.get('boardShot');if(sid&&episode(c)&&M.production.shots(c.e).some(s=>s.id===sid))c.e.selectedShotId=sid;const prev=c.e.navigation||{};c.e.navigation={stage:c.e.stage,view:c.e.view,import:imported(c)?params?.get('import')||prev.import||'pages':undefined,shotId:c.e.selectedShotId,panelId:c.e.view==='canvas'&&c.e.creationCanvas?.selected?.startsWith('panel:')?c.e.creationCanvas.selected.slice(6):params?.get('panel')||prev.panelId,clipId:c.e.editing?.selectedId,canvasSelected:c.e.creationCanvas?.selected};c.p.lastChapterId=c.c.id;M.save();}
 function resume(c){const n=c.e.navigation||{};return url(c,n.stage||c.e.stage||'story',n.view||c.e.view||'flow',imported(c)?'&import='+(n.import||'pages'):n.panelId&&!episode(c)?'&panel='+encodeURIComponent(n.panelId):'');}
 function adaptations(c){return (c.p.episodes||[]).filter(ep=>ep.sourceChapterIds?.includes(c.c.id));}
 function handoff(c,ep){const cc=M.context(c.p.id,ep.id),s=M.production.shots(cc.e).find(s=>M.adaptation.differences(cc,s).length);return url(cc,'boards','flow',s?'&shot='+encodeURIComponent(s.id)+'&compare=1':'');}
 function status(c){if(imported(c)){const d=c.e.importDraft,missing=(d.files||[]).filter(f=>M.imports.storage(f.mediaId)==='reconnect').length,volatile=(d.files||[]).filter(f=>M.imports.storage(f.mediaId)==='session').length;return `${c.e.boards?.length||0}格 · ${missing?missing+'份原图待重连':volatile?volatile+'份原图仅会话，刷新需重连':d.status==='confirmed'?'资料已确认':'资料待确认'}`;}
  if(episode(c)){const ss=M.production.shots(c.e),auto=ss.filter(s=>s.direction?.adoption?.mode==='automatic-review').length,used=ss.filter(s=>s.adoptedId).length,failed=ss.filter(s=>s.candidates?.[0]?.status==='failed').length,diff=ss.filter(s=>M.adaptation.differences(c,s).length).length;return `${used}/${ss.length}镜头采用${auto?' · '+auto+'项自动初稿待审阅':''}${failed?' · '+failed+'项生成失败':''}${diff?' · '+diff+'项来源变化':''}${c.e.editing?' · '+c.e.editing.clips.length+'个剪辑使用':''}`;}
  const bs=c.e.boards||[],used=bs.filter(b=>b.comic?.adoptedId).length,failed=bs.filter(b=>b.comic?.images?.[0]?.status==='failed').length;return `${used}/${bs.length}格采用${failed?' · '+failed+'格生成失败':''} · ${adaptations(c).length}部关联动画`;
 }
 function task(c){const n=c.e.navigation||{},key=imported(c)?n.import||'pages':n.stage||c.e.stage,stage=stages(c).find(([k])=>k===key)?.[1]||({assets:'脚本与资产',story:'本集剧本'}[key])||'继续创作',ss=episode(c)?M.production.shots(c.e):[],si=ss.findIndex(s=>s.id===c.e.selectedShotId),ci=c.e.editing?.clips.findIndex(x=>x.id===c.e.editing.selectedId);return `${stage} · ${(n.view||c.e.view)==='canvas'?'画布':'流程'}${episode(c)&&['audio','review'].includes(key)&&ci>=0?' · 使用'+(ci+1):si>=0?' · 镜头'+(si+1):''}`;}
 M.navigation={stages,current,url,remember,resume,adaptations,handoff,status,task,imported,episode};return M;
};
